CREATE DATABASE IF NOT EXISTS ridehub CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ridehub;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('user','admin') DEFAULT 'user',phone VARCHAR(30),city VARCHAR(80),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS bikes (id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(160) NOT NULL,brand VARCHAR(80) NOT NULL,model VARCHAR(80) NOT NULL,year INT NOT NULL,price DECIMAL(12,2) NOT NULL,city VARCHAR(80) NOT NULL,fuel_type VARCHAR(30) NOT NULL,mileage DECIMAL(6,2),description TEXT,image_url TEXT,seller_name VARCHAR(120),seller_phone VARCHAR(30),status ENUM('active','sold') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS events (id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,description TEXT,date DATE NOT NULL,location VARCHAR(180) NOT NULL,image_url TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS fuel_expenses (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,amount DECIMAL(10,2) NOT NULL,litres DECIMAL(8,2),fuel_price DECIMAL(8,2),odometer INT,expense_date DATE NOT NULL,notes VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS service_reminders (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(160) NOT NULL,due_date DATE NOT NULL,type VARCHAR(50) DEFAULT 'Service',FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS posts (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,content TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
